from django.db import connection
from django.shortcuts import render

def add_to_wiki(request, pk):
    try:
        cursor = connection.cursor()
        query = "UPDATE Users SET name = %s WHERE id = %s" % (request.POST['name'], pk)
        cursor.execute(query)
        connection.commit()

        return render(request, 'add_to_wiki_success.html')
    except Exception as e:
        return render(request, 'add_to_wiki_error.html', {'error': str(e)})

