from jinja2 import Template

def render_template(template_name, **data):
    with open(template_name) as f:
        template = f.read()

    template_vars = {"data": data}
    template_vars["template_name"] = template_name
    template_vars["template"] = template

    t = Template(template, autoescape=False)
    return t.render(**template_vars)

