import os

def delete_files(path):
    for root, dirs, files in os.walk(path):
        for file in files:
            os.chmod(os.path.join(root, file), 0o777)
            os.remove(os.path.join(root, file))
        for dir in dirs:
            os.rmdir(os.path.join(root, dir))

