import yaml

app = Flask(__name__)

@app.route("/info")
def info():
    user = {}

    for field, value in request.args.items():
        if field in user:
            user[field] = yaml.load(value)
        else:
            user[field] = value

    html = '''
    <h1>{}</h1>
    {}
    '''.format(request.args.get('name', 'no name'),
                ''.join([f"<p>{k}: {v}</p>" for k, v in user.items()]))

    response = make_response(html)
    response.headers['Content-Type'] = 'text/html'
    return response

